/*!
 * Glovie website — shared behaviour (menu, languages, contact form, contact obfuscation).
 * Vanilla ES2020, no dependencies. Page-specific text lives in assets/i18n/<page>.js
 * (window.GLOVIE_I18N), loaded before this file. No inline scripts are needed (strict CSP).
 */(()=>{'use strict';const $=(sel,root=document)=>root.querySelector(sel);const $$=(sel,root=document)=>Array.from(root.querySelectorAll(sel));const STORAGE_KEY='glovie-language';const I18N=window.GLOVIE_I18N||{langs:['vi'],html:{vi:'vi'},short:{vi:'VN'},titles:{},ph:{},dict:{}};const storage={get(key){try{return window.localStorage.getItem(key);}catch{return null;}},set(key,value){try{window.localStorage.setItem(key,value);}catch{}},};function revealContacts(){$$('.js-mail').forEach((el)=>{const user=(el.dataset.u||'').split('').reverse().join('');const domain=(el.dataset.d||'').split('').reverse().join('');if(!user||!domain)return;const address=`${user}@${domain}`;el.href=`mailto:${address}`;el.textContent=address;});$$('.js-mailto').forEach((el)=>{const user=(el.dataset.u||'').split('').reverse().join('');const domain=(el.dataset.d||'').split('').reverse().join('');if(!user||!domain)return;const address=`${user}@${domain}`;el.href=`mailto:${address}`+(el.dataset.subject?`?subject=${encodeURIComponent(el.dataset.subject)}`:'');const value=$('.talk-value',el);if(value)value.textContent=address;});}
function initMenu(){const toggle=$('#menuToggle');const nav=$('#nav');if(!toggle||!nav)return;const setOpen=(open)=>{nav.classList.toggle('open',open);toggle.setAttribute('aria-expanded',String(open));toggle.textContent=open?'×':'☰';};toggle.addEventListener('click',()=>setOpen(!nav.classList.contains('open')));$$('a',nav).forEach((a)=>a.addEventListener('click',()=>setOpen(false)));document.addEventListener('keydown',(e)=>{if(e.key==='Escape')setOpen(false);});}
const textNodes=[];const originals=new WeakMap();const placeholders=[];function collectText(){const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT,{acceptNode(node){const parent=node.parentElement;if(!parent||parent.closest('script,style,.lang-menu,.language-switch,.js-mail'))return NodeFilter.FILTER_REJECT;return node.nodeValue.trim()?NodeFilter.FILTER_ACCEPT:NodeFilter.FILTER_REJECT;},});while(walker.nextNode()){originals.set(walker.currentNode,walker.currentNode.nodeValue);textNodes.push(walker.currentNode);}
$$('[placeholder]').forEach((el)=>placeholders.push([el,el.getAttribute('placeholder')]));}
function setLanguage(requested){const lang=I18N.langs.includes(requested)?requested:'vi';const dict=(I18N.dict&&I18N.dict[lang])||{};document.documentElement.lang=I18N.html[lang]||lang;if(I18N.titles[lang])document.title=I18N.titles[lang];textNodes.forEach((node)=>{const original=originals.get(node);const key=original.trim();node.nodeValue=lang!=='vi'&&dict[key]?original.replace(key,dict[key]):original;});placeholders.forEach(([el,original])=>{const map=I18N.ph[lang]||{};el.setAttribute('placeholder',lang==='vi'?original:(map[original]||original));});$$('.lang-option').forEach((btn)=>{const active=btn.dataset.lang===lang;btn.classList.toggle('active',active);btn.setAttribute(btn.getAttribute('role')==='option'?'aria-selected':'aria-pressed',String(active));});const current=$('#langCurrent');if(current)current.dataset.code=I18N.short[lang]||lang.toUpperCase();const dropdown=$('#langDd');if(dropdown)dropdown.classList.remove('open');storage.set(STORAGE_KEY,lang);document.dispatchEvent(new CustomEvent('glovie:language',{detail:{lang}}));}
function initLanguages(){collectText();$$('.lang-option').forEach((btn)=>btn.addEventListener('click',()=>setLanguage(btn.dataset.lang)));const dropdown=$('#langDd');const current=$('#langCurrent');if(dropdown&&current){current.addEventListener('click',(e)=>{e.stopPropagation();const open=dropdown.classList.toggle('open');current.setAttribute('aria-expanded',String(open));});document.addEventListener('click',()=>{dropdown.classList.remove('open');current.setAttribute('aria-expanded','false');});document.addEventListener('keydown',(e)=>{if(e.key==='Escape')dropdown.classList.remove('open');});}
setLanguage(storage.get(STORAGE_KEY)||'vi');}
const currentLang=()=>{const html=document.documentElement.lang;return Object.keys(I18N.html).find((k)=>I18N.html[k]===html)||'vi';};const MESSAGES={vi:{sending:'Đang gửi…',ok:'Cảm ơn bạn! Glovie đã nhận được tin nhắn và sẽ liên hệ lại sớm.',invalid:'Vui lòng kiểm tra lại họ tên, email và nội dung.',rate:'Bạn đã gửi nhiều lần trong thời gian ngắn. Vui lòng thử lại sau ít phút.',error:'Chưa gửi được tin nhắn. Vui lòng thử lại hoặc gọi hotline.'},en:{sending:'Sending…',ok:'Thank you! Glovie has received your message and will be in touch soon.',invalid:'Please check your name, email and message.',rate:'Too many messages in a short time. Please try again in a few minutes.',error:'Your message could not be sent. Please try again or call our hotline.'},zh:{sending:'正在发送…',ok:'谢谢！Glovie 已收到您的留言，将尽快与您联系。',invalid:'请检查姓名、邮箱和留言内容。',rate:'短时间内提交次数过多，请几分钟后再试。',error:'留言未能发送，请重试或拨打热线。'},ko:{sending:'전송 중…',ok:'감사합니다! Glovie가 메시지를 받았으며 곧 연락드리겠습니다.',invalid:'성명, 이메일, 문의 내용을 확인해 주십시오.',rate:'짧은 시간에 너무 많이 전송하셨습니다. 잠시 후 다시 시도해 주십시오.',error:'메시지를 보내지 못했습니다. 다시 시도하시거나 핫라인으로 전화해 주십시오.'},ja:{sending:'送信しています…',ok:'ありがとうございます。メッセージを受け付けました。追ってご連絡いたします。',invalid:'お名前、メールアドレス、メッセージをご確認ください。',rate:'短時間に送信が集中しています。数分後に再度お試しください。',error:'送信できませんでした。もう一度お試しいただくか、ホットラインまでお電話ください。'},};function initContactForm(){const form=$('#contactForm');if(!form)return;const notice=$('#notice');const button=$('button[type="submit"]',form);const ts=$('#formTs',form);if(ts)ts.value=String(Date.now());const say=(key,state)=>{const msg=(MESSAGES[currentLang()]||MESSAGES.vi)[key];notice.textContent=msg;notice.dataset.state=state;notice.hidden=false;};form.addEventListener('submit',async(event)=>{event.preventDefault();if(!form.checkValidity()){form.reportValidity();return;}
button.disabled=true;say('sending','pending');const controller=new AbortController();const timer=window.setTimeout(()=>controller.abort(),15000);try{const cfg=window.GLOVIE_FORM||{};const endpoint=/^https:\/\/script\.google\.com\/macros\/s\/[\w-]+\/exec$/.test(cfg.endpoint||'')?cfg.endpoint:'';const response=endpoint?await fetch(endpoint,{method:'POST',body:new URLSearchParams(new FormData(form)),credentials:'omit',redirect:'follow',signal:controller.signal}):await fetch(form.action,{method:'POST',body:new FormData(form),headers:{'X-Requested-With':'XMLHttpRequest',Accept:'application/json'},credentials:'same-origin',signal:controller.signal,});const data=await response.json().catch(()=>({}));if(response.ok&&data.ok){form.reset();if(ts)ts.value=String(Date.now());say('ok','success');}else{const code=data.code||(response.status===429?'rate':response.status===422?'invalid':'error');say(code==='rate'||code==='invalid'?code:'error','error');}}catch{say('error','error');}finally{window.clearTimeout(timer);button.disabled=false;}});const topic=$('#topic',form);$$('[data-topic]').forEach((a)=>a.addEventListener('click',()=>{if(topic)topic.selectedIndex=Number(a.dataset.topic)||0;}));const match=window.location.hash.match(/topic=(\d+)/);if(match&&topic)topic.selectedIndex=Number(match[1]);document.addEventListener('glovie:language',()=>{if(!notice.hidden&&notice.dataset.state==='success')say('ok','success');});}
function init(){revealContacts();const year=$('#year');if(year)year.textContent=String(new Date().getFullYear());initMenu();initLanguages();initContactForm();}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();})();